import { Injectable } from '@angular/core';
import { Observable } from 'rxjs';
import { environment } from '../../../../environments/environment';
import { HttpClient, HttpParams } from '@angular/common/http';

@Injectable({
  providedIn: 'root',
})
export class TwoStepVerificationService {

  constructor(private http: HttpClient) {}


  verifyResetToken(token: string): Observable<any> {
    const params = new HttpParams().set('token', token);
    return this.http.get<any>(`${environment.BACKEND_URL}/auth/admin/forgot-password/verify-token`, { params });
  }
  verifyOtp(data: { otp: number, token: string }): Observable<any> {
    return this.http.post<any>(`${environment.BACKEND_URL}/auth/admin/forgot-password/verify-otp`, data);
  }
  updatePassword(data: { password: string, token: string }): Observable<any> {
    return this.http.post<any>(`${environment.BACKEND_URL}/auth/admin/forgot-password/update-password`, data);
  }
  
}
