import { Component } from '@angular/core';
import { Router } from '@angular/router';
import { routes } from 'src/app/core/helpers/routes';
import { TwoStepVerificationService } from './two-step-verification.service';

@Component({
  selector: 'app-two-step-verification',
  templateUrl: './two-step-verification.component.html',
  styleUrl: './two-step-verification.component.scss',
})
export class TwoStepVerificationComponent {
  public routes = routes;
  public verifedToken: boolean | null = null;
  public otpDigits: string[] = ['', '', '', ''];

  constructor(
    private router: Router,
    private twoStepVerificationService: TwoStepVerificationService
  ) {
    this.onInit()
  }
  onInit() {
    const token = localStorage.getItem('reset-password-token');
    if (token) {
      this.twoStepVerificationService.verifyResetToken(token).subscribe({
        next: (res) => {
          console.log(res);
          if (res.results.token_verified) {
            this.verifedToken = true;
          } else {
            this.verifedToken = false;
            localStorage.removeItem("reset-password-token");
          }
        },
        error: (err) => {
          if (
            err.error?.status_type === 'RESPONSE_STATUS_UNAUTHORIZED'
          ) {
            this.verifedToken = false;
            localStorage.removeItem("reset-password-token");
          }
        }
      });
    } else {
      this.router.navigate(['/forgot-password']);
    }
  }
  
  verifyOtp() {
    const token = localStorage.getItem('reset-password-token');
    const otp = this.otpDigits.join('');
  
    if (!token || otp.length !== 4 || !/^\d+$/.test(otp)) {
      alert('Invalid OTP or missing token');
      return;
    }
  
    const payload = {
      otp: Number(otp),
      token
    };
  
    this.twoStepVerificationService.verifyOtp(payload).subscribe({
      next: (res) => {
        console.log('OTP Verified:', res);
        // Navigate or show success
        this.router.navigate(['/reset-password']);
      },
      error: (err) => {
        console.error('OTP Verification Failed:', err);
        alert('Invalid OTP. Please try again.');
      }
    });
  }
  
}
