import { Component } from '@angular/core';
import { Router } from '@angular/router';
import { routes } from 'src/app/core/helpers/routes';
import { TwoStepVerificationService } from '../../two-step-verification/two-step-verification/two-step-verification.service';

@Component({
  selector: 'app-reset-password',
  templateUrl: './reset-password.component.html',
  styleUrl: './reset-password.component.scss'
})
export class ResetPasswordComponent {
  public routes = routes;
  public password : boolean[] = [false];
  public verifedToken: boolean | null = null;
  public passwordVisibility: boolean[] = [false, false];
  public newPassword: string = '';
  public confirmPassword: string = '';
  
  
  togglePassword(index: number) {
    this.passwordVisibility[index] = !this.passwordVisibility[index];
  }
  constructor(private router: Router, private twoStepVerificationService: TwoStepVerificationService) {
    this.onInit()
  }
  onInit() {
    const token = localStorage.getItem('reset-password-token');
    if (token) {
      this.twoStepVerificationService.verifyResetToken(token).subscribe({
        next: (res) => {
          console.log(res);
          if (res.results.token_verified) {
            this.verifedToken = true;
          } else {
            this.verifedToken = false;
            localStorage.removeItem("reset-password-token");
          }
        },
        error: (err) => {
          if (
            err.error?.status_type === 'RESPONSE_STATUS_UNAUTHORIZED'
          ) {
            this.verifedToken = false;
            localStorage.removeItem("reset-password-token");
          }
        }
      });
    } else {
      this.router.navigate(['/forgot-password']);
    }
  }
  updatePassword() {
    const token = localStorage.getItem('reset-password-token');
  
    if (!token) {
      alert('Session expired. Please try again.');
      this.router.navigate(['/forgot-password']);
      return;
    }
  
    if (!this.newPassword || !this.confirmPassword) {
      alert('Please enter all fields.');
      return;
    }
  
    if (this.newPassword !== this.confirmPassword) {
      alert('Passwords do not match.');
      return;
    }
  
    const payload = {
      password: this.newPassword,
      token: token
    };
  
    this.twoStepVerificationService.updatePassword(payload).subscribe({
      next: (res) => {
        console.log('Password updated successfully', res);
        localStorage.removeItem('reset-password-token');
        this.router.navigate(['/sign-in']);
      },
      error: (err) => {
        console.error('Password update failed', err);
        alert('Something went wrong. Please try again.');
      }
    });

}
}
